SELECT P.id , P.title , P.summary , P.view_count , P.published_at , P.thumbnail_key , P.thumbnail_metadata , P.comment_count , T.name AS tag_name FROM ( SELECT A.id , A.title , A.summary , A.view_count , A.published_at , C.key AS thumbnail_key , C.metadata AS thumbnail_metadata , (SELECT COUNT(*) FROM comments WHERE post_id = A.id AND deleted_at IS NULL) AS comment_count FROM posts A LEFT JOIN attachments B ON B.record_id = TEXT(A.id) AND B.record_type = 'post' AND B.name = 'thumbnail' LEFT JOIN blobs C ON C.id = B.blob_id WHERE A.post_type = #{postType}
ORDER BY A.view_count ${sortDir}, A.published_at DESC
ORDER BY A.published_at ${sortDir}
ORDER BY A.published_at DESC
LIMIT #{limit} OFFSET #{offset} ) P LEFT JOIN post_tags PT ON PT.post_id = P.id LEFT JOIN tags T ON T.id = PT.tag_id
ORDER BY P.view_count ${sortDir}, P.published_at DESC
ORDER BY P.published_at ${sortDir}
ORDER BY P.published_at DESC

SELECT COUNT(*)
FROM posts
WHERE post_type = #{postType}
